using System;using System.IO;using System.Text;using System.Text.Json;using System.Net;using System.Net.Sockets;using System.Net.Security;using System.Security.Authentication;using System.Security.Cryptography;using System.Security.Cryptography.X509Certificates;using System.Collections.Generic;using System.Collections.Concurrent;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;
class DeckTV {
 static string Dir=AppContext.BaseDirectory,State,Token;static Config C;static X509Certificate2 Cert;static TcpListener Public;static readonly object Gate=new object();static SemaphoreSlim Clients=new SemaphoreSlim(8);static ConcurrentDictionary<string,Session> Sessions=new ConcurrentDictionary<string,Session>();static ConcurrentDictionary<string,object> Jobs=new ConcurrentDictionary<string,object>();static byte[] Screen;static long LastLogin;static int Attempts;static string Host;
 class Config{public string username{get;set;}="admin";public string salt{get;set;}="";public string hash{get;set;}="";public bool enabled{get;set;}=false;}
 class Session{public string csrf;public DateTime expires;}
 class Request{public string method,path;public Dictionary<string,string> headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);public JsonElement data;public string Get(string k){return headers.ContainsKey(k)?headers[k]:"";}}
 static string Random(){byte[] b=new byte[32];RandomNumberGenerator.Fill(b);return Convert.ToBase64String(b).Replace("+","-").Replace("/","_").TrimEnd('=');}
 static string Hash(string p,string salt){using(var h=new Rfc2898DeriveBytes(p,Convert.FromBase64String(salt),150000,HashAlgorithmName.SHA256))return Convert.ToBase64String(h.GetBytes(32));}
 static bool Equal(string a,string b){return CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(a??""),Encoding.UTF8.GetBytes(b??""));}
 static string Text(JsonElement d,string key){return d.ValueKind==JsonValueKind.Object&&d.TryGetProperty(key,out var v)&&v.ValueKind==JsonValueKind.String?v.GetString():"";}
 static bool Flag(JsonElement d,string key){return d.ValueKind==JsonValueKind.Object&&d.TryGetProperty(key,out var v)&&v.ValueKind==JsonValueKind.True;}
 static void Save(){var path=Path.Combine(State,"auth.json");File.WriteAllText(path+".new",JsonSerializer.Serialize(C));File.Move(path+".new",path,true);}
 static void Credentials(JsonElement d){var u=Text(d,"username");var p=Text(d,"password");if(!System.Text.RegularExpressions.Regex.IsMatch(u,"^[A-Za-z0-9_.-]{3,40}$")||p.Length<5||p.Length>256)throw new Exception("Benutzername: 3–40 Zeichen; Passwort: mindestens 5 Zeichen.");var salt=new byte[16];RandomNumberGenerator.Fill(salt);C.username=u;C.salt=Convert.ToBase64String(salt);C.hash=Hash(p,C.salt);Sessions.Clear();Save();}
 static async Task Main(string[] args){if(args.Length==1&&args[0]=="--health-check"){int code=ServiceHealth.Probe();if(code==0)Console.WriteLine("DECK_HEALTH_OK "+ServiceHealth.Version);Environment.Exit(code);return;}State=Path.Combine(Dir,"state");Directory.CreateDirectory(State);Token=File.ReadAllText(Path.Combine(State,"control-token")).Trim();Host=File.ReadAllText(Path.Combine(State,"host")).Trim();C=File.Exists(Path.Combine(State,"auth.json"))?JsonSerializer.Deserialize<Config>(File.ReadAllText(Path.Combine(State,"auth.json"))):new Config();Cert=new X509Certificate2(Path.Combine(State,"server.pfx"),"",X509KeyStorageFlags.EphemeralKeySet);var local=new TcpListener(IPAddress.Loopback,8844);local.Start();LauncherGuard.Init();_ = Task.Run(()=>PrivacyPolicy.Init());if(C.enabled&&C.hash!="")StartPublic();Console.WriteLine("DeckTV local controller ready");while(true){var client=await local.AcceptTcpClientAsync();_ = Serve(client,true);}}
 static void StartPublic(){lock(Gate){if(Public!=null)return;Public=new TcpListener(IPAddress.Any,8843);Public.Start();var listener=Public;_ = Task.Run(async()=>{while(listener==Public){try{var client=await listener.AcceptTcpClientAsync();_ = Serve(client,false);}catch{break;}}});}}
 static void StopPublic(){lock(Gate){var old=Public;Public=null;old?.Stop();Sessions.Clear();}}
 static async Task Serve(TcpClient client,bool local){if(!await Clients.WaitAsync(0)){client.Close();return;}try{client.ReceiveTimeout=10000;client.SendTimeout=10000;using(client){Stream stream=client.GetStream();if(!local){var ssl=new SslStream(stream,false);var handshake=ssl.AuthenticateAsServerAsync(Cert,false,SslProtocols.Tls12,false);if(await Task.WhenAny(handshake,Task.Delay(10000))!=handshake)throw new Exception("TLS timeout");await handshake;stream=ssl;}using(stream){try{var r=Read(stream);await Route(stream,r,local);}catch(Exception e){try{Reply(stream,400,new{error=e.Message.Length>200?"Anfrage fehlgeschlagen":e.Message},local);}catch{}}}}}catch{}finally{Clients.Release();}}
 static Request Read(Stream s){var b=new MemoryStream();int last=0;while(b.Length<16384){int c=s.ReadByte();if(c<0)throw new Exception("Verbindung geschlossen");b.WriteByte((byte)c);last=(last<<8)|c;if(last==0x0d0a0d0a)break;}if(b.Length>=16384)throw new Exception("Header zu groß");var lines=Encoding.ASCII.GetString(b.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);var first=lines[0].Split(' ');if(first.Length!=3)throw new Exception("Ungültige Anfrage");var r=new Request{method=first[0],path=first[1].Split('?')[0]};foreach(var line in lines){int n=line.IndexOf(':');if(n>0)r.headers[line.Substring(0,n)]=line.Substring(n+1).Trim();}if(r.Get("Transfer-Encoding")!="")throw new Exception("Transfer-Encoding nicht unterstützt");int size=0;if(r.Get("Content-Length")!=""&&!int.TryParse(r.Get("Content-Length"),out size))throw new Exception("Ungültige Länge");if(size<0||size>16384)throw new Exception("Anfrage zu groß");byte[] body=new byte[size];int offset=0;while(offset<size){int n=s.Read(body,offset,size-offset);if(n==0)throw new Exception("Unvollständig");offset+=n;}r.data=JsonDocument.Parse(size==0?"{}":Encoding.UTF8.GetString(body)).RootElement.Clone();return r;}
 static void Reply(Stream s,int code,object data,bool local=false,string type="application/json",string extra=""){byte[] bytes=data as byte[]??Encoding.UTF8.GetBytes(JsonSerializer.Serialize(data));string headers="HTTP/1.1 "+code+" "+(code==200?"OK":"Response")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nX-Frame-Options: DENY\r\nContent-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'\r\n"+extra+(local?"Access-Control-Allow-Origin: *\r\nAccess-Control-Allow-Headers: Content-Type, X-Deck-Control\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\n":"")+"\r\n";var h=Encoding.ASCII.GetBytes(headers);s.Write(h,0,h.Length);s.Write(bytes,0,bytes.Length);}
 static Session Auth(Request r){string token="";foreach(var part in r.Get("Cookie").Split(';')){var p=part.Trim();if(p.StartsWith("deck_session="))token=p.Substring(13);}if(Sessions.TryGetValue(token,out var session)&&session.expires>DateTime.UtcNow)return session;return null;}
 static async Task Route(Stream s,Request r,bool local){
 if(local){if(r.method=="OPTIONS"){Reply(s,200,new{},true);return;}if(!Equal(r.Get("X-Deck-Control"),Token)){Reply(s,403,new{error="Lokale Freigabe fehlt"},true);return;}if(r.path=="/launcher/status"&&r.method=="GET"){Reply(s,200,LauncherGuard.Status(),true);return;}if(r.path=="/launcher/pulse"&&r.method=="POST"){Reply(s,200,LauncherGuard.Pulse(Flag(r.data,"visible")),true);return;}if(r.path=="/health"&&r.method=="GET"){Reply(s,200,ServiceHealth.Status(),true);return;}if(r.path=="/privacy"&&r.method=="GET"){Reply(s,200,PrivacyPolicy.Status(),true);return;}if(r.path=="/privacy"&&r.method=="POST"){Reply(s,200,PrivacyPolicy.Set(Flag(r.data,"enabled")),true);return;}if(r.path=="/backend/feed"&&r.method=="GET"){Reply(s,200,ReleaseFeed.Status(),true);return;}if(r.path=="/backend/feed"&&r.method=="POST"){Reply(s,200,ReleaseFeed.Save(Text(r.data,"url")),true);return;}if(r.path=="/backend/check"&&r.method=="POST"){Reply(s,200,ReleaseFeed.Check(),true);return;}if(r.path=="/backend/updates"&&r.method=="GET"){Reply(s,200,BackendUpdates.Status(),true);return;}if((r.path=="/backend/install"||r.path=="/backend/rollback")&&r.method=="POST"){if(!Flag(r.data,"confirm"))throw new Exception("Bestätigung fehlt");Reply(s,200,BackendUpdates.Queue(r.path.EndsWith("rollback")),true);return;}if(r.path=="/updates/rollback"&&r.method=="POST"){if(!Flag(r.data,"confirm"))throw new Exception("Bestätigung fehlt");LauncherGuard.Disarm();Reply(s,200,LauncherUpdates.Rollback(),true);return;}if(r.path=="/apps/cleanup"&&r.method=="POST"){Reply(s,200,ApplicationPolicy.Clean(Text(r.data,"keep")),true);return;}if(r.path=="/updates"&&r.method=="GET"){Reply(s,200,LauncherUpdates.Status(),true);return;}if(r.path=="/updates/install"&&r.method=="POST"){if(!Flag(r.data,"confirm"))throw new Exception("Bestätigung fehlt");LauncherGuard.Disarm();Reply(s,200,LauncherUpdates.Install(),true);return;}if(r.path=="/status"){Reply(s,200,new{enabled=C.enabled,configured=C.hash!="",username=C.username,version=ServiceHealth.Version,boot_persistent=false,url="https://"+Host+":8843"},true);return;}if(r.method!="POST"){Reply(s,405,new{},true);return;}if(r.path=="/credentials"){Credentials(r.data);Reply(s,200,new{message="Zugang gespeichert"},true);return;}if(r.path=="/enabled"){bool enabled=Flag(r.data,"enabled");if(enabled&&C.hash=="")throw new Exception("Zuerst Benutzername und Passwort festlegen");if(enabled)StartPublic();else StopPublic();C.enabled=enabled;Save();Reply(s,200,new{enabled},true);return;}Reply(s,404,new{},true);return;}
 if(r.Get("Host")!=Host+":8843"){Reply(s,403,new{error="Ungültiger Host"});return;}
 if(r.method=="GET"&&(r.path=="/"||r.path=="/app.js"||r.path=="/input.js"||r.path=="/style.css")){string name=r.path=="/"?"index.html":r.path.Substring(1);Reply(s,200,File.ReadAllBytes(Path.Combine(Dir,"static",name)),false,name.EndsWith(".html")?"text/html; charset=utf-8":name.EndsWith(".css")?"text/css":"text/javascript");return;}
 if(r.method=="POST"&&(r.Get("Origin")!="https://"+Host+":8843"||!r.Get("Content-Type").StartsWith("application/json"))){Reply(s,403,new{error="Ungültiger Ursprung"});return;}
 if(r.path=="/api/login"&&r.method=="POST"){lock(Gate){long now=DateTimeOffset.UtcNow.ToUnixTimeSeconds();if(now-LastLogin>60){Attempts=0;LastLogin=now;}if(++Attempts>6)throw new Exception("Zu viele Versuche; eine Minute warten");if(C.hash==""||!Equal(Text(r.data,"username"),C.username)||!Equal(Hash(Text(r.data,"password"),C.salt),C.hash))throw new Exception("Zugangsdaten falsch");var token=Random();var se=new Session{csrf=Random(),expires=DateTime.UtcNow.AddHours(8)};Sessions[token]=se;Reply(s,200,new{csrf=se.csrf},false,"application/json","Set-Cookie: deck_session="+token+"; Secure; HttpOnly; SameSite=Strict; Path=/; Max-Age=28800\r\n");}return;}
 var session=Auth(r);if(session==null){Reply(s,401,new{error="Bitte anmelden"});return;}if(r.method=="POST"&&!Equal(r.Get("X-CSRF-Token"),session.csrf)){Reply(s,403,new{error="Ungültige Sitzung"});return;}
 if(r.path=="/api/backend/updates"&&r.method=="GET"){Reply(s,200,BackendUpdates.Status());return;}
 if(r.path=="/api/backend/feed"&&r.method=="GET"){Reply(s,200,ReleaseFeed.Status());return;}
 if(r.path=="/api/backend/feed"&&r.method=="POST"){Reply(s,200,ReleaseFeed.Save(Text(r.data,"url")));return;}
 if(r.path=="/api/backend/check"&&r.method=="POST"){Reply(s,200,ReleaseFeed.Check());return;}
 if((r.path=="/api/backend/install"||r.path=="/api/backend/rollback")&&r.method=="POST"){if(!Flag(r.data,"confirm"))throw new Exception("Bestätigung fehlt");Reply(s,200,BackendUpdates.Queue(r.path.EndsWith("rollback")));return;}
 if(r.path=="/api/session"){Reply(s,200,new{csrf=session.csrf,host=Host,username=C.username,apps=new{},mode="tv",pointer=false,text_input=false});return;}
 if(r.path=="/api/device"){Reply(s,200,new{device=new{modelName="Samsung Smart Monitor",resolution="1920x1080 Capture",developerMode=(string)null},time=DateTimeOffset.UtcNow.ToUnixTimeSeconds()});return;}
 if(r.path=="/api/screen"){var frame=Screen;if(frame==null){Reply(s,404,new{error="Noch keine Aufnahme"});return;}Reply(s,200,frame,false,"image/png");return;}
 if(r.path.StartsWith("/api/jobs/")){if(Jobs.TryGetValue(r.path.Substring(10),out var job))Reply(s,200,job);else Reply(s,404,new{});return;}
 if(r.method!="POST"){Reply(s,404,new{});return;}
 if(r.path=="/api/logout"){session.expires=DateTime.MinValue;Reply(s,200,new{ok=true});return;}
 if(r.path=="/api/password"){if(!Equal(Hash(Text(r.data,"current"),C.salt),C.hash))throw new Exception("Aktuelles Passwort falsch");Credentials(r.data);Reply(s,200,new{message="Zugang geändert; bitte neu anmelden"});return;}
 if(r.path=="/api/input"||r.path=="/api/remote"){Reply(s,200,Input(r.data));return;}
 if(r.path!="/api/capture"&&r.path!="/api/read"&&r.path!="/api/launch"&&r.path!="/api/console"&&r.path!="/api/update"){Reply(s,404,new{});return;}
 string id=Random();if(Jobs.Count>100)Jobs.Clear();Jobs[id]=new{status="running"};var data=r.data;string path=r.path;_ = Task.Run(()=>{lock(Gate){try{Jobs[id]=new{status="done",result=Command(path,data)};}catch(Exception e){Jobs[id]=new{status="error",error=e.Message};}}});Reply(s,202,new{job=id});await Task.CompletedTask;
 }
 static object Run(string command){var p=new Process{StartInfo=new ProcessStartInfo("/bin/sh"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true}};p.StartInfo.ArgumentList.Add("-c");p.StartInfo.ArgumentList.Add(command);p.Start();var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(30000)){p.Kill(true);throw new Exception("Befehlszeitlimit erreicht");}return new{output=output.Result+error.Result,exit_code=p.ExitCode,mode="root",uid=0,smack="User",cleaned=false};}
 static object Command(string path,JsonElement d){if(path=="/api/capture"){string file="/tmp/deck-frame-"+Guid.NewGuid().ToString("N")+".png";try{Run("enlightenment_info -dump_screen -p /tmp/ -n "+Path.GetFileName(file));var bytes=File.ReadAllBytes(file);if(bytes.Length>8388608||bytes.Length<8||bytes[0]!=137||bytes[1]!=80)throw new Exception("Ungültige Aufnahme");Screen=bytes;return new{captured_at=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()/1000.0,message="Bildschirmaufnahme aktualisiert."};}finally{if(File.Exists(file))File.Delete(file);}}
 if(path=="/api/console"){if(!Flag(d,"confirm_root")||Text(d,"mode")!="root")throw new Exception("Auf dem TV erfordert die Konsole den bestätigten Root-Modus");string command=Text(d,"command");if(command.Length==0||command.Length>4000||command.Contains('\0'))throw new Exception("Ungültiger Befehl");return Run(command);}
 if(path=="/api/update")return Run("vconftool set -f -t int db/menu/support/softwareupdate/autoupdate "+(Flag(d,"enabled")?"1":"0"));
 if(path=="/api/launch"){var apps=new Dictionary<string,string>{{"plex","kIciSQlYEM.plex"},{"moonlight","MoonLightS.MoonlightWasm"},{"youtube","9Ur5IzDKqV.TizenYouTube"},{"browser","org.tizen.browser"}};if(!apps.ContainsKey(Text(d,"app")))throw new Exception("Unbekannte App");return Run("app_launcher -s "+apps[Text(d,"app")]);}
 if(path=="/api/read"&&Text(d,"kind")=="metrics")return ReadMetrics();
 var commands=new Dictionary<string,string>{{"metrics","cat /proc/uptime; cat /proc/loadavg; cat /proc/meminfo | head -5"},{"processes","ps -eo pid,ppid,user,stat,comm,args | head -160"},{"services","systemctl list-units --type=service --all --no-pager --no-legend"},{"packages","pkgcmd -l -t tpk; pkgcmd -l -t wgt"},{"logs","journalctl -n 100 --no-pager -o short-iso"},{"network","cat /proc/net/dev"},{"capabilities","id; uname -r; cat /proc/self/attr/current"}};var kind=Text(d,"kind");if(!commands.ContainsKey(kind))throw new Exception("Unbekannte Diagnose");return Run(commands[kind]);}
 static object ReadMetrics(){
 var values=new Dictionary<string,long>();foreach(var line in File.ReadAllLines("/proc/meminfo")){var parts=line.Split(new[]{' ',':','\t'},StringSplitOptions.RemoveEmptyEntries);if(parts.Length>1&&long.TryParse(parts[1],out var value))values[parts[0]]=value;}
 long total=values.ContainsKey("MemTotal")?values["MemTotal"]:0,free=values.ContainsKey("MemAvailable")?values["MemAvailable"]:values.ContainsKey("MemFree")?values["MemFree"]:0;
 long? diskTotal=null,diskUsed=null;try{var drive=new DriveInfo("/opt");diskTotal=drive.TotalSize/1024;diskUsed=(drive.TotalSize-drive.AvailableFreeSpace)/1024;}catch{}
 var uptime=File.ReadAllText("/proc/uptime").Split(' ')[0];var fields=File.ReadAllText("/proc/loadavg").Split(' ');var loads=new[]{fields[0],fields[1],fields[2]};
 return new{output="Live /proc metrics",exit_code=0,metrics=new{uptime,load=loads,memory_total_kb=total,memory_used_kb=Math.Max(0,total-free),disk_total_kb=diskTotal,disk_used_kb=diskUsed,auto_update=(bool?)null,identity="Native TV service",raw="/proc + /opt filesystem"}};
 }
 static object Input(JsonElement d){return NativeInput.Send(d);}
}
